mapper.select:
SELECT interviewer_id, interviewer_name, interviewer_gender, profile_image_url, interviewer_prompt, voice_type, language
FROM ai_interviewer
WHERE language = #{language}
ORDER BY RAND()
LIMIT #{count}

SELECT applicant_id, applicant_name, applicant_gender, applicant_type, profile_image_url, applicant_prompt, voice_type, language
FROM ai_applicant
WHERE applicant_type = #{applicantType}
  AND language = #{language}
ORDER BY RAND()
LIMIT #{count}
